"""Validation result and report models."""

from __future__ import annotations

from datetime import datetime
from enum import Enum

from pydantic import BaseModel, Field

from app.models.invoice import ExtractionResult

DISCLAIMER = (
    "This report is generated by an automated assistance tool. It is not a certification "
    "that the invoice is GST-compliant or approved for filing, and it is not a substitute for "
    "review by a qualified GST practitioner or chartered accountant. Tax rates come from a local, "
    "versioned reference dataset that must be verified against official CBIC notifications."
)


class CheckStatus(str, Enum):
    PASS = "PASS"
    FAIL = "FAIL"  # invalid information
    MISSING = "MISSING"  # information not found on the invoice
    WARNING = "WARNING"  # suspicious or inconsistent
    MANUAL_REVIEW = "MANUAL_REVIEW"  # cannot be verified automatically


class Severity(str, Enum):
    ERROR = "error"
    WARNING = "warning"
    INFO = "info"


class CheckCategory(str, Enum):
    FIELDS = "Required fields"
    GSTIN = "GSTIN"
    HSN = "HSN/SAC & rate"
    CALCULATION = "Tax calculation"
    SUPPLY = "Place of supply"


class OverallStatus(str, Enum):
    VALID = "VALID"
    INVALID = "INVALID"
    NEEDS_REVIEW = "NEEDS REVIEW"


class ValidationCheck(BaseModel):
    check_id: str = Field(description="Stable identifier, e.g. gstin.supplier.checksum")
    category: CheckCategory
    name: str
    status: CheckStatus
    severity: Severity
    message: str = Field(description="Deterministic finding produced by the rule engine")
    field: str | None = None
    expected: str | None = None
    actual: str | None = None
    explanation: str | None = Field(default=None, description="Plain-language explanation")
    suggestion: str | None = Field(default=None, description="Suggested correction")
    explanation_source: str = "rules"  # "rules" or "llm"


class ValidationSummary(BaseModel):
    total_checks: int
    passed: int
    errors: int
    warnings: int
    manual_review: int = Field(description="Automated findings the rule engine could not verify "
                                           "(checks with status MANUAL_REVIEW). These drive NEEDS REVIEW.")
    standing_reminders: int = Field(
        default=0, description="Verification reminders that apply to every invoice because the tool can "
                               "never automate them (GSTIN registration status, e-invoicing, reverse charge, "
                               "official rate confirmation, OCR re-check)")
    manual_verification_total: int = Field(default=0, description="manual_review + standing_reminders")


class AgentStep(BaseModel):
    step: str
    detail: str


class ValidationReport(BaseModel):
    invoice_id: str
    original_filename: str | None = None
    generated_at: datetime
    overall_status: OverallStatus
    summary: ValidationSummary
    overall_explanation: str
    checks: list[ValidationCheck]
    manual_verification: list[str] = Field(default_factory=list,
                                           description="manual_review_findings followed by standing_reminders")
    manual_review_findings: list[str] = Field(default_factory=list)
    standing_reminders: list[str] = Field(default_factory=list)
    gstin_registration: dict[str, str] = Field(
        default_factory=dict, description="Registration status per party; never reported as active without "
                                          "an authorised live source")
    assumptions: list[str] = Field(default_factory=list)
    extraction: ExtractionResult
    reference_data_version: str
    llm_used: bool = False
    llm_model: str | None = None
    llm_note: str | None = None
    explanation_mode: str = Field(
        default="Rule-based explanations",
        description="Where the explanation text came from (Claude or the rule-based fallback). "
                    "Statuses always come from the rule engine.")
    agent_trace: list[AgentStep] = Field(default_factory=list)
    disclaimer: str = DISCLAIMER
